param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestPath,[Parameter(Mandatory=$true)][string]$HypervisorCMake,[Parameter(Mandatory=$true)][string]$TestsCMake,[Parameter(Mandatory=$true)][string]$ForbiddenPaths)
$ErrorActionPreference='Stop';function A($x,$m){if(-not$x){throw $m}};function O($t,$a,$n){$p=0;foreach($x in $a){$q=$t.IndexOf($x,$p,[StringComparison]::Ordinal);A($q-ge0)"$n $x";$p=$q+$x.Length}}
function V($s,$h,$t,$hc,$tc){
 foreach($x in @('VMX_CR3_RESIDENCY_STATE_VERSION UINT32_C(1)','VMX_CR3_RESIDENCY_MAX_ROOT UINT64_C(0x000ffffffffff000)','VMX_CR3_RESIDENCY_ACTION_REMAIN_OUTSIDE','VMX_CR3_RESIDENCY_ACTION_ENTER','VMX_CR3_RESIDENCY_ACTION_REMAIN_INSIDE','VMX_CR3_RESIDENCY_ACTION_LEAVE','volatile uint32_t Busy','uint32_t Reserved32','VmxCr3ResidencyInitialize(','VmxCr3ResidencyApply(','perform no VMX, hook, EPT')){A($h.Contains($x))"header $x"}
 foreach($x in @('sizeof(VMX_CR3_RESIDENCY_STATE) == 56','sizeof(VMX_CR3_RESIDENCY_TRANSITION) == 96','offsetof(VMX_CR3_RESIDENCY_TRANSITION, Next) == 40')){A($h.Contains($x))"ABI $x"}
 A($s.Contains('Target->NormalizedRoot > VMX_CR3_RESIDENCY_MAX_ROOT'))'root bound';A($s.Contains('State->Busy != 0')-and$s.Contains('State->Reserved32 != 0'))'lock auth'
 O $s @('StateValid(Previous)','DecisionValid(Decision)','!Zero(OutTransition, sizeof(*OutTransition))','Separate(Previous, sizeof(*Previous)','Separate(Decision, sizeof(*Decision)','Previous->TargetGeneration != Decision->Target.Generation','Previous->TransitionSequence == UINT64_MAX','Next.TransitionSequence++','VMX_CR3_RESIDENCY_ACTION_LEAVE','VMX_CR3_RESIDENCY_ACTION_REMAIN_OUTSIDE','if (Decision->Target.Matched)','VMX_CR3_RESIDENCY_ACTION_REMAIN_INSIDE','VMX_CR3_RESIDENCY_ACTION_ENTER','Staged.Next = Next','*OutTransition = Staged') 'apply'
 A($s-notmatch '(?i)ntddk|wdm\.h|wdf\.h|__vmx|vmread|vmwrite|invept|IOCTL|Hook|VMCS_|Dispatcher')'pure source'
 foreach($x in @('remain outside','enter target','KVA-root stay','PCID update','leave target','stale generation','invalid decision','oversized root','sequence overflow','busy state','state/output alias','decision/output alias')){A($t.Contains($x))"test $x"}
 A(([regex]::Matches($hc,'(?m)^\s*vmx_cr3_residency\.c\s*$')).Count-eq1)'source once';A(([regex]::Matches($tc,'add_test\(NAME test_vmx_cr3_residency COMMAND')).Count-eq1)'unit once';A(([regex]::Matches($tc,'test_vmx_cr3_residency_contracts')).Count-eq1)'contract once'
}
$s=Get-Content -Raw $SourcePath;$h=Get-Content -Raw $HeaderPath;$t=Get-Content -Raw $TestPath;$hc=Get-Content -Raw $HypervisorCMake;$tc=Get-Content -Raw $TestsCMake;V $s $h $t $hc $tc
foreach($p in $ForbiddenPaths.Split(',')){A((Get-Content -Raw $p)-notmatch 'VmxCr3Residency|vmx_cr3_residency')"unwired $p"}
$m=@($s.Replace('StateValid(Previous)','1'),$s.Replace('DecisionValid(Decision)','1'),$s.Replace('Previous->TargetGeneration != Decision->Target.Generation','0'),$s.Replace('Target->NormalizedRoot > VMX_CR3_RESIDENCY_MAX_ROOT','0'),$s.Replace('Previous->TransitionSequence == UINT64_MAX','0'),$s.Replace('State->Busy != 0','0'),$s.Replace('Next.TransitionSequence++','Next.TransitionSequence += 2'),$s.Replace('if (Decision->Target.Matched)','if (0)'),$s.Replace('*OutTransition = Staged','memset(OutTransition,0,sizeof(*OutTransition))'));$i=0;foreach($x in $m){$i++;A($x-ne$s)"vacuous $i";$bad=$false;try{V $x $h $t $hc $tc}catch{$bad=$true};A($bad)"accepted $i"}
Write-Host 'PASS: pure CR3 residency transitions authenticate unlocked state and decisions, reject stale generations, preserve failures, and remain unwired.'
